(()=>{const q=document.querySelector('#condition-search');if(!q)return;const groups=[...document.querySelectorAll('.topic')],buttons=[...document.querySelectorAll('.filters button')],methods=document.querySelector('.az-methods'),cards=[...methods.querySelectorAll('.az-method-card')],grid=document.querySelector('.groupgrid'),media=matchMedia('(max-width:700px)');let role=location.hash==='#methods'?'Диагностика и методы':'Все темы';const norm=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').trim();function filter(){let n=0;const words=norm(q.value).split(/\s+/).filter(Boolean);groups.forEach(g=>{let count=0;g.querySelectorAll('.items a').forEach(a=>{a.hidden=!(words.every(w=>norm(a.dataset.search).includes(w))&&(role==='Все темы'||JSON.parse(a.dataset.roles).includes(role)));if(!a.hidden)count++});g.hidden=!count;g.open=words.length||role!=='Все темы'||!media.matches;n+=count});grid.hidden=n===0;let methodsCount=0;cards.forEach(c=>{c.hidden=!((role==='Все темы'||role==='Диагностика и методы')&&words.every(w=>norm(c.textContent+' '+c.dataset.search).includes(w)));if(!c.hidden)methodsCount++});methods.hidden=methodsCount===0;n+=methodsCount;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.textContent===role)));document.querySelector('.empty-results').hidden=n>0;document.querySelector('.resultnote').textContent=words.length||role!=='Все темы'?'Найдено материалов: '+n:'Выберите тему, чтобы узнать о диагностике и подходах к лечению.'}q.addEventListener('input',filter);buttons.forEach(b=>b.addEventListener('click',()=>{role=b.textContent;history.replaceState(null,'',location.pathname+(role==='Диагностика и методы'?'#methods':''));filter()}));document.querySelectorAll('.examples button').forEach(b=>b.addEventListener('click',()=>{role='Все темы';history.replaceState(null,'',location.pathname);q.value=b.textContent;filter();q.focus()}));window.addEventListener('hashchange',()=>{role=location.hash==='#methods'?'Диагностика и методы':'Все темы';filter()});filter();})();